-- statement
INSERT INTO topup_orders(order_id) SELECT NULL WHERE NOT(json_extract(?1,'$.now')>=json_extract(?1,'$.payment.checked_at') AND json_extract(?1,'$.now')<json_extract(?1,'$.payment.verification_deadline') AND json_extract(?1,'$.payment.verification_deadline')=json_extract(?1,'$.payment.checked_at')+60000 AND json_extract(?1,'$.now')<json_extract(?1,'$.order.intent_expires_at'));
-- statement
INSERT OR IGNORE INTO topup_orders(order_id,intent_id,chain_id,token,token_contract,evm_tx_hash,payer_address,recv_address,pay_amount,cid_number,account_id,coin_fen,package_id,status,settlement_claim_id,settlement_claimed_at,gmb_tx_hash,gmb_block_hash,gmb_extrinsic_index,exception_reason,confirmed_at,settled_at,intent_hash,intent_issued_at,intent_expires_at,payer_authorization_hash,wallet_is_contract,evm_block_hash,evm_block_number,evm_transaction_index,evm_log_index,evm_block_time_ms,evm_actual_amount,gmb_evidence_hash) SELECT json_extract(?1,'$.order.order_id'),json_extract(?1,'$.order.intent_id'),json_extract(?1,'$.order.chain_id'),json_extract(?1,'$.order.token'),json_extract(?1,'$.order.token_contract'),json_extract(?1,'$.order.evm_tx_hash'),json_extract(?1,'$.order.payer_address'),json_extract(?1,'$.order.recv_address'),json_extract(?1,'$.order.pay_amount'),json_extract(?1,'$.order.cid_number'),json_extract(?1,'$.order.account_id'),json_extract(?1,'$.order.coin_fen'),json_extract(?1,'$.order.package_id'),json_extract(?1,'$.order.status'),json_extract(?1,'$.order.settlement_claim_id'),json_extract(?1,'$.order.settlement_claimed_at'),json_extract(?1,'$.order.gmb_tx_hash'),json_extract(?1,'$.order.gmb_block_hash'),json_extract(?1,'$.order.gmb_extrinsic_index'),json_extract(?1,'$.order.exception_reason'),json_extract(?1,'$.order.confirmed_at'),json_extract(?1,'$.order.settled_at'),json_extract(?1,'$.order.intent_hash'),json_extract(?1,'$.order.intent_issued_at'),json_extract(?1,'$.order.intent_expires_at'),json_extract(?1,'$.order.payer_authorization_hash'),json_extract(?1,'$.order.wallet_is_contract'),json_extract(?1,'$.order.evm_block_hash'),json_extract(?1,'$.order.evm_block_number'),json_extract(?1,'$.order.evm_transaction_index'),json_extract(?1,'$.order.evm_log_index'),json_extract(?1,'$.order.evm_block_time_ms'),json_extract(?1,'$.order.evm_actual_amount'),json_extract(?1,'$.order.gmb_evidence_hash');
-- statement
INSERT INTO topup_orders(order_id) SELECT NULL WHERE NOT EXISTS(SELECT 1 FROM topup_orders WHERE chain_id=json_extract(?1,'$.order.chain_id') AND evm_tx_hash=json_extract(?1,'$.order.evm_tx_hash') AND
 intent_id IS json_extract(?1,'$.order.intent_id') AND chain_id IS json_extract(?1,'$.order.chain_id') AND token IS json_extract(?1,'$.order.token') AND token_contract IS json_extract(?1,'$.order.token_contract') AND evm_tx_hash IS json_extract(?1,'$.order.evm_tx_hash') AND payer_address IS json_extract(?1,'$.order.payer_address') AND recv_address IS json_extract(?1,'$.order.recv_address') AND pay_amount IS json_extract(?1,'$.order.pay_amount') AND cid_number IS json_extract(?1,'$.order.cid_number') AND account_id IS json_extract(?1,'$.order.account_id') AND coin_fen IS json_extract(?1,'$.order.coin_fen') AND package_id IS json_extract(?1,'$.order.package_id') AND intent_hash IS json_extract(?1,'$.order.intent_hash') AND intent_issued_at IS json_extract(?1,'$.order.intent_issued_at') AND intent_expires_at IS json_extract(?1,'$.order.intent_expires_at') AND payer_authorization_hash IS json_extract(?1,'$.order.payer_authorization_hash') AND wallet_is_contract IS json_extract(?1,'$.order.wallet_is_contract') AND evm_block_hash IS json_extract(?1,'$.order.evm_block_hash') AND evm_block_number IS json_extract(?1,'$.order.evm_block_number') AND evm_transaction_index IS json_extract(?1,'$.order.evm_transaction_index') AND evm_log_index IS json_extract(?1,'$.order.evm_log_index') AND evm_block_time_ms IS json_extract(?1,'$.order.evm_block_time_ms') AND evm_actual_amount IS json_extract(?1,'$.order.evm_actual_amount'));
